# typed: false
# frozen_string_literal: true

# Homebrew formula for the babysit CLI (`bbs`).
#
# Delivers the compiled `bbs` multicall binary. All core bins are now Go,
# reachable as `bbs <sub>` (ticket, config, secrets, upgrade, design,
# dashboard, autopilot, foreman), plus the `bbs-config` / `bbs-env` argv0
# aliases. It does NOT install the
# babysit skill pack (skills and workflows), which
# comes from git clone + go run ./cmd/bbs setup.
#
# Generated by scripts/gen-formula.sh; the release workflow regenerates it with
# real checksums on each tag. Do not hand-edit the sha256 values.
class Bbs < Formula
  desc "2build CLI — Go multicall for config, env, slug, ticket, and more"
  homepage "https://2found.dev/tools/2build/"
  version "1.127.1"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/2found/2build/releases/download/v#{version}/bbs_#{version}_darwin_arm64.tar.gz"
      sha256 "1c7f32bc2bca9b5905f0c5b99437094ab941119d4789ab0c78eec9a2495ffcb1"
    end
    on_intel do
      url "https://github.com/2found/2build/releases/download/v#{version}/bbs_#{version}_darwin_amd64.tar.gz"
      sha256 "6f657db812db115a847f0929fa5df6662dbc648fdf819d61c0ad4abcdeb59a41"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/2found/2build/releases/download/v#{version}/bbs_#{version}_linux_arm64.tar.gz"
      sha256 "8a976064cd7b425f5807a4c3fd63438e4913d5ddb181ed747a47b1ad0ea71623"
    end
    on_intel do
      url "https://github.com/2found/2build/releases/download/v#{version}/bbs_#{version}_linux_amd64.tar.gz"
      sha256 "cfe79cb319fca84ecd334915527395d0f48460205af207fc78b9b7207b525cdd"
    end
  end

  def install
    bin.install "bbs"
    # Multicall aliases: dispatch keys on argv0, so bbs-<name> runs "bbs <name>".
    # Only subcommands the CLI registers today are aliased.
    bin.install_symlink bin/"bbs" => "bbs-config"
    bin.install_symlink bin/"bbs" => "bbs-env"
  end

  test do
    assert_match "Usage:", shell_output("#{bin}/bbs --help")
    assert_match "config", shell_output("#{bin}/bbs-config --help")
  end
end
